clc; clearvars;
%%
root_dir = "..";
addpath(genpath(fullfile(root_dir,"O3_Lidar/proc_functions/")))
addpath(genpath(fullfile(root_dir,"signal_analysis/functions/")))

data_path = fullfile(root_dir,"O3_processed_data/");

dataFiles = dir(fullfile(data_path, "*.mat"));
fileNames = string({dataFiles.name});

date = string(datetime(datetime("2024-10-31", "InputFormat", "uuuu-MM-dd"), "Format","uuuuMMdd")); %[control:datePicker:64b4]{"position":[24,75]}
fid = contains(fileNames,date);

if all(fid==0)
    error("no file found for selected data")
end

prof_id = 1;

min_alt = 700;
max_alt = 30e3;

data = load(fullfile(data_path,fileNames(fid)));
%%
% index into averaged profiles
ids_avg = data.ids_avg;

% time and altitude grids
t = data.times(:,2);
z = data.z_vec';

% filter data within certain altitude range
alt_id = z >= min_alt & z <= max_alt;
z = z(alt_id);
zkm = z.*1e-3;

% On PC FR data and PC background
on = fillmissing(data.pc_R_on_fr(alt_id,:),"constant",0);

% Off AN-PC merged FR data and PC background
off = fillmissing(data.pc_R_off_fr(alt_id,:),"constant",0);

% Ozone mixing ratio
qO3 = data.q_o3_pc_fr(alt_id,:);

% Ozone number density
NO3 = fillmissing(data.N_o3_fr_pc(alt_id,:), "constant",0);

% air number density
Na = data.Na(alt_id,:);

% temperature profile
Ta = data.Ta(alt_id,:);

% ozone cross section
sigma_o3_on = data.sigma_o3_on(alt_id,:);
sigma_o3_off = data.sigma_o3_off(alt_id,:);

n_prof = length(find(~isnan(ids_avg)));
%%
%[text] Produce synthetic profile here
% Ozone Absorption Cross Section
BDM = load("..\signal_analysis\cross_sections\ozone\bdm\bdm_287_299.mat");

% Ozone profile
N_O3 = NO3;

% Air number density
Nair = Na(:,prof_id);

% On and off wavelengths
lam_on = 287.2e-9;
lam_off = 299.1e-9;

% Ozone absorption cross section
% sigma_o3_on = sigma_o3_on;
% sigma_o3_off = sigma_o3_off;

% Emitted pulse power at each wavelength
% E0_on = 10.6e-3;
% E0_off = 6.3e-3;
E0_on = 50e-3;
E0_off = 50e-3;

% Efficiency factor at each wavelength
eta_on = 1;
eta_off = 1;

% Detector quantum efficiency
etaQ = 0.7;

% Telescope primary area
t_r = .2;   % Radius of the receiver in meters
o_r = 0.1;  % Radius of the obstruction
A = pi.*(t_r^2 - o_r^2);

% DAQ sampling rate
f = 40e6;
tau = 1/f; % Laser pulse duration

% Overlap function
O = ones(size(z));

% Dead-time constant
fd = 270e6;
tau_d = 1./ fd; % 3.7 ns

% Sampling rate
fs = 40e6;
tau_s = 1/fs;

navg = 1200;
%%
% initial coefficient values
x0 = [1 0 0];

% conversion between counts and counting rate in MHz
rate2count = tau .*1e6;
count2rate = 1 ./ rate2count;

% initialize arrays to hold fitting coefficients and fitted profiles
x_on = NaN(length(x0),n_prof);
x_off = NaN(length(x0),n_prof);

on_sim_fit = NaN(size(on));
off_sim_fit = NaN(size(off));
for i=1:n_prof
    id_avg = ids_avg(i);

    if isnan(id_avg)
        continue;
    end

    on_tmp =  on(:,i) ./ navg;
    off_tmp = off(:,i) ./ navg;

    sigma_o3_on_temp = sigma_o3_on(:,id_avg);
    sigma_o3_off_temp = sigma_o3_off(:,id_avg);
    N_O3_tmp = N_O3(:,id_avg);

    fun_on =  @(x0,z1) add_deadtime(signal(z1, lam_on,  E0_on,  A, tau, x0(1), etaQ, Nair, sigma_o3_on_temp,  N_O3_tmp, O)  + z .* x0(2) + x0(3), tau_d, tau_s);
    fun_off = @(x0,z1) add_deadtime(signal(z1, lam_off, E0_off, A, tau, x0(1), etaQ, Nair, sigma_o3_off_temp, N_O3_tmp, O)  + z .* x0(2) + x0(3), tau_d, tau_s);

    opt=optimoptions("lsqcurvefit","Display","off");

    x_on(:,i) =  lsqcurvefit(fun_on, x0, z, on_tmp,  [0 0 0], [], opt);
    x_off(:,i) = lsqcurvefit(fun_off,x0, z, off_tmp, [0 0 0], [], opt);
    on_sim_fit(:,i) = fun_on(x_on(:,i),z);
    off_sim_fit(:,i) = fun_off(x_off(:,i),z);

    break
end

on_off_plt = cat(3, on, off) .* count2rate ./ navg;

[on_sim_fit,on_sim_fit_nsy] = add_noise(on_sim_fit,0,navg);
[off_sim_fit,off_sim_fit_nsy] = add_noise(off_sim_fit,0,navg);

on_sim_fit_nsy = on_sim_fit_nsy .* count2rate;
off_sim_fit_nsy = off_sim_fit_nsy .* count2rate;

on_off_sim_fit_plt = cat(3, on_sim_fit_nsy, off_sim_fit_nsy);
%%
y_lim = [1e0 1e3];

on_off_dispname = ["On" "Off"];
prof_plot(zkm, squeeze(on_off_plt(:,prof_id,:)), [], y_lim, "Altitude (km)","Count Rate (MHz)","Real Lidar Signals",on_off_dispname) %[output:0d3d027b]
on_off_sim_dispname = ["On" "Off"];
prof_plot(zkm, squeeze(on_off_sim_fit_plt(:,prof_id,:)), [], y_lim, "Altitude (km)","Count Rate (MHz)","Simulated and Fitted Lidar Signals",on_off_sim_dispname) %[output:861ba4a3]
figure; %[output:84a5623c]
scatter(squeeze(on_off_plt(:,prof_id,:)), squeeze(on_off_sim_fit_plt(:,prof_id,:))) %[output:84a5623c]
title("Real v Sim") %[output:84a5623c]
xlabel("Real Data") %[output:84a5623c]
ylabel("Simulated Data") %[output:84a5623c]
prof_plot(zkm,N_O3(:,prof_id)) %[output:605b4366] %[output:50dad67c]
%%
figure; %[output:27466f0c]
yyaxis left %[output:27466f0c]
plot(x_on(1,:)) %[output:27466f0c]
hold on  %[output:27466f0c]
plot(x_off(1,:)) %[output:27466f0c]
hold off %[output:27466f0c]
xlabel("Profile Index") %[output:27466f0c]
ylabel("Efficiency Factor") %[output:27466f0c]
legend("On","Off","Location","best") %[output:27466f0c]
grid on %[output:27466f0c]
yyaxis right %[output:27466f0c]
plot(x_on(2,:)) %[output:27466f0c]
hold on %[output:27466f0c]
plot(x_off(2,:)) %[output:27466f0c]
hold off %[output:27466f0c]
ylabel("Transmittance Factor") %[output:27466f0c]
legend("Efficiency Factor On","Efficiency Factor Off","Transmittance Factor On","Transmittance Factor Off","Location","best") %[output:27466f0c]
c_lim = y_lim;

im_plot(t,zkm,on_off_plt(:,:,1),c_lim,[],"","","MHz","On Signal Real",12); %[output:248a5cfb]
im_plot(t,zkm,on_off_plt(:,:,2),c_lim,[],"","","MHz","Off Signal Real",12); %[output:7250a4d3]
im_plot(t,zkm,on_off_sim_fit_plt(:,:,1),c_lim,[],"","","MHz","On Signal Simulated",12); %[output:640dff40]
im_plot(t,zkm,on_off_sim_fit_plt(:,:,2),c_lim,[],"","","MHz","Off Signal Simulated",12); %[output:177e8244]
%%
function im_plot(x,y,z,c_lim,y_lim,x_label,y_label,c_label,title_str,fs)
    figure;
    I = imagesc(x, y, z);
    cbar_tolnet=colorbar_tolnet_func;
    colormap(cbar_tolnet);
    ax = gca;

    set(gca, 'ColorScale', 'log')

    if ~isempty(c_lim)
        ax.CLim = c_lim;
    end

    set(gca,'YDir','normal');
    set(I,'AlphaData',~isnan(z));

    if ~isempty(y_lim)
        ylim(y_lim)
    end
    c = colorbar;
    c.Label.String = c_label;
    xlabel(x_label)
    ylabel(y_label)
    title(title_str)
    fontsize(fs,"points")
end

function prof_plot(x,y,x_lim,y_lim,x_label,y_label,title_str,disp_name)
    arguments
        x 
        y 
        x_lim       = []
        y_lim       = []
        x_label     = []
        y_label     = []
        title_str   = []
        disp_name   = []
    end

    n_prof = size(y,2);

    figure;
    hold on
    for i=1:n_prof
        if ~isempty(disp_name)
            plot(x,y(:,i),'DisplayName',disp_name(i))
            legend 
        else
            plot(x,y(:,i))
        end
    end
    hold off

    yscale log
    grid on

    if ~isempty(x_lim)
        xlim(x_lim)
    end

    if ~isempty(y_lim)
        ylim(y_lim)
    end

    if ~isempty(x_label)
        xlabel(x_label)
    end

    if ~isempty(y_label)
        ylabel(y_label)
    end

    if ~isempty(title_str)
        title(title_str)
    end
end

function R = add_deadtime(P, tau_d, tau_s)
    R = P ./ (1 + (P * (tau_d/tau_s)));
end

